export function frameBytes(value){if(ArrayBuffer.isView(value))return value.byteLength;if(Array.isArray(value)){if(!value.length||typeof value[0]==='number')return value.length*8+64;return value.reduce((n,v)=>n+frameBytes(v),64);}if(value&&typeof value==='object')return Object.values(value).reduce((n,v)=>n+frameBytes(v),128);return 16;}
export class FrameCache{
 constructor(load,{maxEntries=12,maxBytes=128*1024*1024}={}){this.load=load;this.maxEntries=maxEntries;this.maxBytes=maxBytes;this.entries=new Map();this.tasks=new Map();this.bytes=0;this.running=0;this.hits=0;this.misses=0;this.generation=0;}
 has(key){return this.entries.has(key);}
 get(key,priority=1){const cached=this.entries.get(key);if(cached){this.entries.delete(key);this.entries.set(key,cached);if(priority)this.hits++;return Promise.resolve(cached.value);}let task=this.tasks.get(key);if(task){task.priority=Math.max(task.priority,priority);this.pump();return task.promise;}if(priority)this.misses++;task={key,priority,controller:new AbortController(),running:false,generation:this.generation};task.promise=new Promise((resolve,reject)=>Object.assign(task,{resolve,reject}));this.tasks.set(key,task);this.pump();return task.promise;}
 pump(){while(this.running<2){const active=[...this.tasks.values()].filter(t=>t.running);const queued=[...this.tasks.values()].filter(t=>!t.running).sort((a,b)=>b.priority-a.priority);const task=queued.find(t=>t.priority||!active.some(a=>!a.priority));if(!task)return;task.running=true;this.running++;Promise.resolve().then(()=>this.load(task.key,task.controller.signal)).then(value=>{if(task.controller.signal.aborted||task.generation!==this.generation)throw new DOMException('Cancelled','AbortError');const bytes=frameBytes(value);if(bytes<=this.maxBytes){this.entries.set(task.key,{value,bytes});this.bytes+=bytes;while(this.entries.size>this.maxEntries||this.bytes>this.maxBytes){const [key,entry]=this.entries.entries().next().value;this.entries.delete(key);this.bytes-=entry.bytes;}}task.resolve(value);},error=>task.reject(error)).catch(error=>task.reject(error)).finally(()=>{if(this.tasks.get(task.key)===task)this.tasks.delete(task.key);this.running--;this.pump();});}}
 prefetch(keys){const keep=new Set(keys);for(const [key,t]of this.tasks){if(!t.priority&&!keep.has(key)){t.controller.abort();this.tasks.delete(key);if(!t.running){t.reject(new DOMException('Cancelled','AbortError'));}}}for(const key of keys)this.get(key,0).catch(()=>{});}
 clear(){this.generation++;this.entries.clear();this.bytes=0;for(const [key,t]of this.tasks){t.controller.abort();this.tasks.delete(key);if(!t.running){t.reject(new DOMException('Cancelled','AbortError'));}}}
 debug(){return {frames:this.entries.size,bytes:this.bytes,hits:this.hits,misses:this.misses,pending:this.tasks.size};}
}
